40	test("Manual captures charge an order in parts #e2e", async ({ page }) => {
41	  // Arrange
42	  const orderPage = new OrderPage(page);
43	
44	  await orderPage.goto(await findOrderId(config, "unpaid"));
45	
46	  // Read rather than computed: the scenario's shipping method has a seeded, random price.
47	  const total = await orderPage.readTotal();
48	  const firstPart = 1;
49	
50	  // Act & Assert
51	  await test.step("a capture below the total leaves the order partly charged", async () => {
52	    await orderPage.captureManually({ description: "first part", amount: firstPart });
53	    await expect(orderPage.paymentStatusBadges).toContainText("Not fully charged");
54	    await expect(orderPage.statusInfo).toHaveText("Unfulfilled");
55	  });
56	
57	  await test.step("capturing the rest charges it fully", async () => {
58	    await orderPage.captureManually({ description: "second part", amount: total - firstPart });
59	    await expect(orderPage.paymentStatusBadges).toContainText("Fully charged");
60	    await expect(orderPage.transactions.getByText("Manual capture")).toHaveCount(2);
61	  });
62	});
63	
64	test("Addresses stay editable before and after fulfillment #e2e", async ({ page }) => {
65	  // Arrange
66	  const orderPage = new OrderPage(page);
67	  const change = { firstName: "Grace", streetAddress1: "1 Main Street" };
68	
69	  // Act & Assert
70	  await test.step("shipping address of an unfulfilled order", async () => {
71	    await orderPage.goto(await findOrderId(config, "unpaid"));
72	    await orderPage.editShippingAddressButton.click();
73	    await orderPage.addressDialog.changeAddress(change);
74	    await expect(orderPage.shippingAddressSection).toContainText(change.streetAddress1);
75	    await expect(orderPage.billingAddressSection).not.toContainText(change.streetAddress1);
76	  });
77	
78	  await test.step("billing address of a fulfilled order", async () => {
79	    await orderPage.goto(await findOrderId(config, "fulfilled"));
80	    await expect(orderPage.statusInfo).toHaveText("Fulfilled");
81	    await orderPage.editBillingAddressButton.click();
82	    await orderPage.addressDialog.changeAddress(change);
83	    await expect(orderPage.billingAddressSection).toContainText(change.streetAddress1);
84	    await expect(orderPage.shippingAddressSection).not.toContainText(change.streetAddress1);
85	  });
86	});
